void sort_scores(std::vector<int>& scores) {
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (size_t i = 0; i < scores.size() - 1; ++i) {
            if (scores[i] > scores[i + 1]) {
                std::swap(scores[i], scores[i + 1]);
                swapped = true;
            }
        }
    }
