struct Node { int val; Node *left, *right; };

int height(Node* root) {
    if (!root) return 0;
    std::stack<std::pair<Node*, int>> s;
    s.push({root, 1});
    int max_h = 0;
    while(!s.empty()) {
        auto [node, h] = s.top(); s.pop();
        max_h = std::max(max_h, h);
        if (node->left) s.push({node->left, h+1});
        if (node->right) s.push({node->right, h+1});
    }
    return max_h;
}
---For very deep or unbalanced trees (like linked lists), recursive tree traversal can blow the stack. An iterative DFS using `std::stack` moves the storage to the heap.

